window.docContents[115].resolve({"/rules/PL1002/#PL1002-limitations":{"contents":"In the editor the rule is reported for completed declarations of the current snapshot. A cancelled collection reports nothing for that declaration; a failed one is reported as PL2005 (incomplete), never as an invented PL1002.\n\nThe checked example below comes from a diagnostic single-file inspection that keeps Lean's sorry warning as related evidence and continues to policy inspection; the ordinary project commands stop earlier with PL2003, as described above.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1002: Proof holes are forbidden","header":"Limitations and unsupported cases","id":"/rules/PL1002/#PL1002-limitations"},"/rules/PL2001/#PL2001-limitations":{"contents":"This page's example is a diagnostic demonstration: the violating run is INCOMPLETE by design and is not accepted negative evidence. Its corrected counterpart passed a completed positive check.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2001: The declared Lean environment must be available","header":"Limitations and unsupported cases","id":"/rules/PL2001/#PL2001-limitations"},"/versions/#versions":{"contents":"\n\n\n\n\n\n\n\n\n\n","context":"Plumb for Lean rule reference","header":"Versions and evidence","id":"/versions/#versions"}});